381	                groups={plan.groups}
382	                selectedEntityId={selectedEntityId}
383	                onSelectEntity={setSelectedEntityId}
384	                onOpenNewCloneModal={handleOpenCreateEntityModal}
385	                onMoveEntity={handleMoveEntity}
