399	                  onRefresh={handleScan}
400	                  onExecutePlan={handleExecutePlan}
401	                  isExecuting={isExecuting}
402	                  addToast={addToast}
403	                  mockMode={mockMode}
404	                  onToggleMockMode={handleToggleMockMode}
405	                  onResetMockData={handleResetMockData}
406	                  selectedEntityId={selectedEntityId}
407	                  onSelectEntity={setSelectedEntityId}
408	                  onOpenCreateModal={handleOpenCreateEntityModal}
409	                  onRenameEntity={handleRenameEntity}
410	                  onTrashFolder={handleTrashFolder}
411	                />
412	              </div>
413	            </div>
414	          ) : (
415	            <div style={{ padding: '3rem', textAlign: 'center', color: 'var(--text-dim)' }}>
416	              Loading entities workspace...
417	            </div>
418	          )
419	        )}
420	      </main>
421	
422	      {/* PK Network Golden Standard Entity Modal */}
423	      {plan && (
424	        <NewEntityModal
425	          isOpen={isNewEntityModalOpen}
426	          onClose={() => setIsNewEntityModalOpen(false)}
427	          availableGroups={plan.groups}
428	          defaultGroupId={targetCreateGroupId}
429	          onCreate={handleCreateNewEntity}
430	          templateName="Entropy 0 Archetype"
431	        />
432	      )}
433	
434	      {/* Target Folders Configuration Modal */}
435	      <TargetConfigModal
436	        isOpen={isConfigOpen}
437	        onClose={() => setIsConfigOpen(false)}
438	        templateLink={templateLink}
439	        setTemplateLink={setTemplateLink}
440	        rootLink={rootLink}
441	        setRootLink={setRootLink}
442	        onSaved={() => {
