312	        )}
313	      </div>
314	
315	      {/* 2. Subfolders Listing */}
316	      <div className="card" style={{ padding: '0', overflow: 'hidden' }}>
317	        <div style={{ padding: '0.75rem 1.25rem', borderBottom: '1px solid var(--border-light)', background: 'var(--bg-card-hover)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
318	          <span style={{ fontSize: '12.5px', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.04em', color: 'var(--text-dim)' }}>
319	            Folders ({browseData?.subfolders.length || 0})
