342	                  cursor: 'pointer',
343	                }}
344	                className="table-row-hover"
345	                onClick={() => fetchFolder(fld.id)}
346	              >
347	                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
348	                  <Folder size={18} style={{ color: fld.source_id ? '#c084fc' : 'var(--accent)' }} />
349	                  <div>
350	                    <div style={{ fontWeight: 600, fontSize: '13.5px', color: 'var(--text-primary)' }}>
351	                      {fld.name}
352	                    </div>
353	                    {fld.description && (
354	                      <div style={{ fontSize: '11px', color: 'var(--text-dim)', maxWidth: '500px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
355	                        {fld.description}
356	                      </div>
357	                    )}
358	                  </div>
359	                </div>
360	
361	                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }} onClick={(e) => e.stopPropagation()}>
