import React, { useState, useEffect } from 'react';
import {
  Folder,
  FolderPlus,
  FileEdit,
  Trash2,
  ExternalLink,
  ChevronRight,
  ArrowUpLeft,
  RotateCw,
  Zap,
  File,
  Search,
  Check,
  X,
} from 'lucide-react';
import { BrowseResponse, DriveFolderItem, DriveFileItem } from '../types';

interface DriveNavigatorProps {
  initialFolderId: string;
  templateLink: string;
  addToast: (type: 'success' | 'error' | 'info', title: string, message?: string) => void;
}

interface Crumb {
  id: string;
  name: string;
}

export const DriveNavigator: React.FC<DriveNavigatorProps> = ({
  initialFolderId,
  templateLink,
  addToast,
}) => {
  const [currentFolderId, setCurrentFolderId] = useState<string>(initialFolderId);
  const [breadcrumbs, setBreadcrumbs] = useState<Crumb[]>([]);
  const [browseData, setBrowseData] = useState<BrowseResponse | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  // Jump Input
  const [jumpInput, setJumpInput] = useState('');

  // Modals
  const [isCloneModalOpen, setIsCloneModalOpen] = useState(false);
  const [cloneName, setCloneName] = useState('');
  const [cloneTemplate, setCloneTemplate] = useState(templateLink);
  const [isCloning, setIsCloning] = useState(false);

  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [newFolderName, setNewFolderName] = useState('');

  const [renameTarget, setRenameTarget] = useState<DriveFolderItem | null>(null);
  const [renameValue, setRenameValue] = useState('');

  const [trashTarget, setTrashTarget] = useState<DriveFolderItem | null>(null);

  // Fetch Folder Contents
  const fetchFolder = async (folderId: string, addToHistory = true) => {
    setIsLoading(true);
    try {
      const res = await fetch(`/api/drive/browse?folder_id=${encodeURIComponent(folderId)}`);
      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.detail || 'Failed to browse folder');
      }
      setBrowseData(data);
      setCurrentFolderId(data.current_folder.id);

      if (addToHistory) {
        setBreadcrumbs((prev) => {
          const idx = prev.findIndex((c) => c.id === data.current_folder.id);
          if (idx !== -1) {
            return prev.slice(0, idx + 1);
          }
          return [...prev, { id: data.current_folder.id, name: data.current_folder.name }];
        });
      }
    } catch (err: any) {
      addToast('error', 'Navigation Failed', err.message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (initialFolderId) {
      fetchFolder(initialFolderId);
    }
  }, [initialFolderId]);

  // Jump to pasted ID or URL
  const handleJump = (e: React.FormEvent) => {
    e.preventDefault();
    if (!jumpInput.trim()) return;
    fetchFolder(jumpInput.trim());
    setJumpInput('');
  };

  // Navigate Up
  const handleNavigateUp = () => {
    if (breadcrumbs.length > 1) {
      const parentCrumb = breadcrumbs[breadcrumbs.length - 2];
      fetchFolder(parentCrumb.id);
    }
  };

  // Spawn Clone
  const handleSpawnClone = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!cloneName.trim()) return;
    setIsCloning(true);
    try {
      const res = await fetch('/api/drive/clone_template', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          parent_id: currentFolderId,
          clone_name: cloneName.trim(),
          template_link: cloneTemplate.trim() || templateLink,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Failed to spawn clone');

      addToast(
        'success',
        'Entity Clone Spawned!',
        `Created '${cloneName}' with ${data.total_folders_created} stamped subfolders`
      );
      setIsCloneModalOpen(false);
      setCloneName('');
      fetchFolder(currentFolderId, false);
    } catch (err: any) {
      addToast('error', 'Clone Spawning Error', err.message);
    } finally {
      setIsCloning(false);
    }
  };

  // Create Regular Folder
  const handleCreateFolder = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newFolderName.trim()) return;
    try {
      const res = await fetch('/api/drive/create_folder', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          parent_id: currentFolderId,
          name: newFolderName.trim(),
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Failed to create folder');
      addToast('success', 'Folder Created', `Created folder '${newFolderName}'`);
      setIsCreateModalOpen(false);
      setNewFolderName('');
      fetchFolder(currentFolderId, false);
    } catch (err: any) {
      addToast('error', 'Folder Creation Failed', err.message);
    }
  };

  // Rename Folder
  const handleRename = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!renameTarget || !renameValue.trim()) return;
    try {
      const res = await fetch('/api/drive/rename_folder', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          folder_id: renameTarget.id,
          name: renameValue.trim(),
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Failed to rename folder');
      addToast('success', 'Folder Renamed', `'${renameTarget.name}' → '${renameValue}'`);
      setRenameTarget(null);
      fetchFolder(currentFolderId, false);
    } catch (err: any) {
      addToast('error', 'Rename Failed', err.message);
    }
  };

  // Trash Folder
  const handleTrash = async () => {
    if (!trashTarget) return;
    try {
      const res = await fetch('/api/drive/trash_folder', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          folder_id: trashTarget.id,
          force: false,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Cannot delete folder');
      addToast('success', 'Folder Trashed', `Moved '${trashTarget.name}' to Trash`);
      setTrashTarget(null);
      fetchFolder(currentFolderId, false);
    } catch (err: any) {
      addToast('error', 'Delete Blocked', err.message);
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
      {/* 1. Navigator Header & Breadcrumbs Deck */}
      <div className="card" style={{ padding: '1rem 1.25rem', display: 'flex', flexDirection: 'column', gap: '0.85rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: '0.75rem' }}>
          {/* Breadcrumb Trail */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.35rem', flexWrap: 'wrap' }}>
            {breadcrumbs.length > 1 && (
              <button
                onClick={handleNavigateUp}
                className="btn subtle"
                style={{ padding: '0.3rem 0.6rem', fontSize: '12px' }}
                title="Go up to parent folder"
              >
                <ArrowUpLeft size={14} /> Up
              </button>
            )}
            {breadcrumbs.map((crumb, idx) => (
              <React.Fragment key={crumb.id}>
                {idx > 0 && <ChevronRight size={13} style={{ color: 'var(--text-dim)' }} />}
                <button
                  onClick={() => fetchFolder(crumb.id)}
                  style={{
                    background: idx === breadcrumbs.length - 1 ? 'var(--bg-canvas)' : 'transparent',
                    border: 'none',
                    color: idx === breadcrumbs.length - 1 ? 'var(--accent)' : 'var(--text-secondary)',
                    fontWeight: idx === breadcrumbs.length - 1 ? 700 : 500,
                    fontSize: '13px',
                    cursor: 'pointer',
                    padding: '0.2rem 0.5rem',
                    borderRadius: 'var(--radius-sm)',
                  }}
                >
                  {crumb.name}
                </button>
              </React.Fragment>
            ))}
          </div>

          {/* Quick Jump Bar */}
          <form onSubmit={handleJump} style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
            <input
              type="text"
              placeholder="Jump to Folder URL / ID..."
              value={jumpInput}
              onChange={(e) => setJumpInput(e.target.value)}
              className="input-base"
              style={{ width: '220px', padding: '0.35rem 0.65rem', fontSize: '12px' }}
            />
            <button type="submit" className="btn subtle" style={{ padding: '0.35rem 0.65rem', fontSize: '12px' }}>
              <Search size={13} />
            </button>
          </form>
        </div>

        {/* Current Folder Metadata Strip & Action Toolbar */}
        {browseData && (
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderTop: '1px solid var(--border-light)', paddingTop: '0.75rem', flexWrap: 'wrap', gap: '0.75rem' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.65rem' }}>
              <Folder size={18} style={{ color: 'var(--accent)' }} />
              <span style={{ fontWeight: 700, fontSize: '15px' }}>{browseData.current_folder.name}</span>
              {browseData.current_folder.source_id && (
                <span className="badge badge-match" title="This folder is an entity clone derived from a template archetype">
                  ⚡ Clone (src: {browseData.current_folder.source_id.slice(0, 8)}...)
                </span>
              )}
              <a
                href={`https://drive.google.com/drive/folders/${browseData.current_folder.id}`}
                target="_blank"
                rel="noreferrer"
                style={{ color: 'var(--text-dim)', display: 'inline-flex', alignItems: 'center', marginLeft: '0.3rem' }}
                title="Open in Google Drive"
              >
                <ExternalLink size={14} />
              </a>
            </div>

            {/* Action Buttons */}
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <button
                onClick={() => setIsCloneModalOpen(true)}
                className="btn primary"
                style={{ padding: '0.4rem 0.85rem', fontSize: '12.5px', background: '#9333ea', borderColor: '#a855f7' }}
              >
                <Zap size={14} /> Spawn Stamped Clone...
              </button>
              <button
                onClick={() => setIsCreateModalOpen(true)}
                className="btn secondary"
                style={{ padding: '0.4rem 0.85rem', fontSize: '12.5px' }}
              >
                <FolderPlus size={14} /> New Folder
              </button>
              <button
                onClick={() => fetchFolder(currentFolderId, false)}
                className="btn subtle"
                style={{ padding: '0.4rem 0.65rem', fontSize: '12.5px' }}
                title="Refresh Folder Contents"
              >
                <RotateCw size={14} className={isLoading ? 'spinner' : ''} />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* 2. Subfolders Listing */}
      <div className="card" style={{ padding: '0', overflow: 'hidden' }}>
        <div style={{ padding: '0.75rem 1.25rem', borderBottom: '1px solid var(--border-light)', background: 'var(--bg-card-hover)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span style={{ fontSize: '12.5px', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.04em', color: 'var(--text-dim)' }}>
            Folders ({browseData?.subfolders.length || 0})
          </span>
          <span style={{ fontSize: '11.5px', color: 'var(--text-dim)' }}>
            Double-click or click to open
          </span>
        </div>

        {browseData?.subfolders.length === 0 ? (
          <div style={{ padding: '2.5rem', textAlign: 'center', color: 'var(--text-dim)', fontSize: '13.5px' }}>
            No subfolders found in this directory. Click "Spawn Stamped Clone" or "New Folder" above.
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column' }}>
            {browseData?.subfolders.map((fld) => (
              <div
                key={fld.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  padding: '0.75rem 1.25rem',
                  borderBottom: '1px solid var(--border-table)',
                  transition: 'background 0.15s ease',
                  cursor: 'pointer',
                }}
                className="table-row-hover"
                onClick={() => fetchFolder(fld.id)}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                  <Folder size={18} style={{ color: fld.source_id ? '#c084fc' : 'var(--accent)' }} />
                  <div>
                    <div style={{ fontWeight: 600, fontSize: '13.5px', color: 'var(--text-primary)' }}>
                      {fld.name}
                    </div>
                    {fld.description && (
                      <div style={{ fontSize: '11px', color: 'var(--text-dim)', maxWidth: '500px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                        {fld.description}
                      </div>
                    )}
                  </div>
                </div>

                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }} onClick={(e) => e.stopPropagation()}>
                  {fld.source_id ? (
                    <span className="badge badge-rename" style={{ fontSize: '11px' }}>
                      ⚡ src: {fld.source_id.slice(0, 8)}...
                    </span>
                  ) : (
                    <span className="badge badge-prune" style={{ fontSize: '11px' }}>
                      Manual
                    </span>
                  )}

                  <button
                    onClick={() => { setRenameTarget(fld); setRenameValue(fld.name); }}
                    className="btn subtle"
                    style={{ padding: '0.25rem 0.45rem' }}
                    title="Rename"
                  >
                    <FileEdit size={13} />
                  </button>

                  <button
                    onClick={() => setTrashTarget(fld)}
                    className="btn subtle"
                    style={{ padding: '0.25rem 0.45rem', color: 'var(--danger)' }}
                    title="Trash folder"
                  >
                    <Trash2 size={13} />
                  </button>

                  <a
                    href={`https://drive.google.com/drive/folders/${fld.id}`}
                    target="_blank"
                    rel="noreferrer"
                    style={{ color: 'var(--text-dim)', padding: '0.25rem' }}
                    title="Open in Google Drive"
                  >
                    <ExternalLink size={13} />
                  </a>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* 3. Files Listing (if any) */}
      {browseData && browseData.files.length > 0 && (
        <div className="card" style={{ padding: '0', overflow: 'hidden' }}>
          <div style={{ padding: '0.75rem 1.25rem', borderBottom: '1px solid var(--border-light)', background: 'var(--bg-card-hover)' }}>
            <span style={{ fontSize: '12.5px', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.04em', color: 'var(--text-dim)' }}>
              Files ({browseData.files.length})
            </span>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column' }}>
            {browseData.files.map((file) => (
              <div
                key={file.id}
                style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0.65rem 1.25rem', borderBottom: '1px solid var(--border-table)' }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.65rem' }}>
                  <File size={16} style={{ color: 'var(--info)' }} />
                  <span style={{ fontSize: '13px', color: 'var(--text-primary)' }}>{file.name}</span>
                </div>
                <a
                  href={`https://drive.google.com/file/d/${file.id}/view`}
                  target="_blank"
                  rel="noreferrer"
                  style={{ color: 'var(--text-dim)' }}
                >
                  <ExternalLink size={13} />
                </a>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ================= MODAL: SPAWN STAMPED CLONE ================= */}
      {isCloneModalOpen && (
        <div className="modal-backdrop">
          <div className="modal-box" style={{ maxWidth: '480px' }}>
            <h3 style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', margin: '0 0 1rem 0' }}>
              <Zap size={18} style={{ color: '#c084fc' }} />
              Spawn Custom Stamped Clone
            </h3>
            <p style={{ fontSize: '13px', color: 'var(--text-secondary)', marginBottom: '1.25rem' }}>
              Creates a brand new entity folder under <strong>{browseData?.current_folder.name}</strong>,
              recursively reproducing the template tree and stamping each folder with immutable <code>src:</code> pointers.
            </p>
            <form onSubmit={handleSpawnClone} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              <div>
                <label style={{ display: 'block', fontSize: '12px', fontWeight: 600, color: 'var(--text-dim)', marginBottom: '0.35rem' }}>
                  New Clone Folder Name (e.g. C25_Elena)
                </label>
                <input
                  type="text"
                  required
                  autoFocus
                  placeholder="Enter specific name..."
                  value={cloneName}
                  onChange={(e) => setCloneName(e.target.value)}
                  className="input-base"
                />
              </div>

              <div>
                <label style={{ display: 'block', fontSize: '12px', fontWeight: 600, color: 'var(--text-dim)', marginBottom: '0.35rem' }}>
                  Template Archetype URL / ID
                </label>
                <input
                  type="text"
                  required
                  value={cloneTemplate}
                  onChange={(e) => setCloneTemplate(e.target.value)}
                  className="input-base"
                />
              </div>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.6rem', marginTop: '0.5rem' }}>
                <button type="button" onClick={() => setIsCloneModalOpen(false)} className="btn subtle" disabled={isCloning}>
                  Cancel
                </button>
                <button type="submit" className="btn primary" style={{ background: '#9333ea', borderColor: '#a855f7' }} disabled={isCloning}>
                  {isCloning ? 'Spawning Folders...' : 'Spawn Stamped Clone'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ================= MODAL: CREATE REGULAR FOLDER ================= */}
      {isCreateModalOpen && (
        <div className="modal-backdrop">
          <div className="modal-box" style={{ maxWidth: '400px' }}>
            <h3 style={{ margin: '0 0 1rem 0' }}>Create New Folder</h3>
            <form onSubmit={handleCreateFolder} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              <input
                type="text"
                required
                autoFocus
                placeholder="Folder name..."
                value={newFolderName}
                onChange={(e) => setNewFolderName(e.target.value)}
                className="input-base"
              />
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.6rem' }}>
                <button type="button" onClick={() => setIsCreateModalOpen(false)} className="btn subtle">
                  Cancel
                </button>
                <button type="submit" className="btn primary">
                  Create
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ================= MODAL: RENAME FOLDER ================= */}
      {renameTarget && (
        <div className="modal-backdrop">
          <div className="modal-box" style={{ maxWidth: '400px' }}>
            <h3 style={{ margin: '0 0 1rem 0' }}>Rename Folder</h3>
            <form onSubmit={handleRename} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              <input
                type="text"
                required
                autoFocus
                value={renameValue}
                onChange={(e) => setRenameValue(e.target.value)}
                className="input-base"
              />
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.6rem' }}>
                <button type="button" onClick={() => setRenameTarget(null)} className="btn subtle">
                  Cancel
                </button>
                <button type="submit" className="btn primary">
                  Save Name
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ================= MODAL: TRASH CONFIRMATION ================= */}
      {trashTarget && (
        <div className="modal-backdrop">
          <div className="modal-box" style={{ maxWidth: '420px', borderColor: 'var(--danger-border)' }}>
            <h3 style={{ margin: '0 0 0.75rem 0', color: 'var(--danger)' }}>Move to Trash?</h3>
            <p style={{ fontSize: '13px', color: 'var(--text-secondary)', marginBottom: '1.25rem' }}>
              Are you sure you want to move <strong>'{trashTarget.name}'</strong> to Google Drive Trash?
              Folders with existing files will be safeguarded from accidental deletion.
            </p>
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.6rem' }}>
              <button type="button" onClick={() => setTrashTarget(null)} className="btn subtle">
                Cancel
              </button>
              <button
                type="button"
                onClick={handleTrash}
                className="btn danger"
                style={{ background: 'var(--danger)', color: 'white' }}
              >
                Confirm Trash
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { MultiEntityPlan, ActionItem, ActionType } from '../types';
import {
  ChevronDown,
  ChevronRight,
  Folder,
  FolderPlus,
  FileEdit,
  Trash2,
  AlertTriangle,
  CheckCircle,
  ExternalLink,
  Filter,
} from 'lucide-react';

interface ReconciliationTreeProps {
  plan: MultiEntityPlan;
}

export const ReconciliationTree: React.FC<ReconciliationTreeProps> = ({ plan }) => {
  const [filterMode, setFilterMode] = useState<'all' | 'actions' | 'anomalies'>('all');
  const [collapsedGroups, setCollapsedGroups] = useState<Record<string, boolean>>({});

  const toggleGroup = (groupId: string) => {
    setCollapsedGroups((prev) => ({
      ...prev,
      [groupId]: !prev[groupId],
    }));
  };

  const getActionBadge = (action: ActionType) => {
    switch (action) {
      case 'CREATE':
        return <span className="badge badge-create">+ CREATE</span>;
      case 'RENAME':
        return <span className="badge badge-rename">✏️ RENAME</span>;
      case 'UPDATE_DESC':
        return <span className="badge badge-update">~ UPDATE DESC</span>;
      case 'PRUNE_EMPTY':
        return <span className="badge badge-prune">🗑️ PRUNE EMPTY</span>;
      case 'FLAG_RED':
        return <span className="badge badge-anomaly">🚨 RED ANOMALY</span>;
      case 'MATCH':
        return <span className="badge badge-match">✓ MATCH</span>;
    }
  };

  const isVisible = (item: ActionItem) => {
    if (filterMode === 'all') return true;
    if (filterMode === 'actions') return item.action_type !== 'MATCH';
    if (filterMode === 'anomalies') return item.action_type === 'FLAG_RED';
    return true;
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
      {/* Outliner Toolbar */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '0.25rem 0',
          flexWrap: 'wrap',
          gap: '0.75rem',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <span style={{ fontSize: '13px', fontWeight: 600, color: 'var(--text-secondary)' }}>
            Target Hierarchy:
          </span>
          <span style={{ fontFamily: 'var(--font-mono)', fontSize: '12px', color: 'var(--accent)' }}>
            {plan.data_root_name} &larr; Archetype: {plan.template_name}
          </span>
        </div>

        {/* Filter Pills */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
          <Filter size={13} style={{ color: 'var(--text-dim)', marginRight: '0.2rem' }} />
          <button
            onClick={() => setFilterMode('all')}
            className={`btn subtle ${filterMode === 'all' ? 'active' : ''}`}
            style={{
              padding: '0.25rem 0.6rem',
              fontSize: '11.5px',
              background: filterMode === 'all' ? 'var(--bg-card-hover)' : 'transparent',
              borderColor: filterMode === 'all' ? 'var(--border-mid)' : 'transparent',
              color: filterMode === 'all' ? 'var(--text-primary)' : 'var(--text-dim)',
            }}
          >
            All ({plan.summary.total_evaluated})
          </button>

          <button
            onClick={() => setFilterMode('actions')}
            className={`btn subtle ${filterMode === 'actions' ? 'active' : ''}`}
            style={{
              padding: '0.25rem 0.6rem',
              fontSize: '11.5px',
              background: filterMode === 'actions' ? 'var(--accent-bg)' : 'transparent',
              borderColor: filterMode === 'actions' ? 'var(--accent)' : 'transparent',
              color: filterMode === 'actions' ? 'var(--accent)' : 'var(--text-dim)',
            }}
          >
            Action Required ({plan.summary.create_count + (plan.summary.rename_count || 0) + plan.summary.update_desc_count + plan.summary.prune_empty_count + plan.summary.flagged_red_count})
          </button>

          <button
            onClick={() => setFilterMode('anomalies')}
            className={`btn subtle ${filterMode === 'anomalies' ? 'active' : ''}`}
            style={{
              padding: '0.25rem 0.6rem',
              fontSize: '11.5px',
              background: filterMode === 'anomalies' ? 'var(--danger-bg)' : 'transparent',
              borderColor: filterMode === 'anomalies' ? 'var(--danger)' : 'transparent',
              color: filterMode === 'anomalies' ? 'var(--danger)' : 'var(--text-dim)',
            }}
          >
            Red Anomalies ({plan.summary.flagged_red_count})
          </button>
        </div>
      </div>

      {/* Groups & Entities Tree */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
        {plan.groups.map((group) => {
          const isCollapsed = collapsedGroups[group.group_id];
          const allGroupItems = group.entity_plans.flatMap((ep) => ep.items);
          const visibleItems = allGroupItems.filter(isVisible);

          if (filterMode !== 'all' && visibleItems.length === 0 && !group.empty_note) {
            return null;
          }

          return (
            <div
              key={group.group_id}
              className="card"
              style={{
                padding: '0',
                overflow: 'hidden',
                borderColor: 'var(--border-light)',
              }}
            >
              {/* Group Header (Level 1: Testament XX) */}
              <div
                onClick={() => toggleGroup(group.group_id)}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  padding: '0.85rem 1.25rem',
                  background: 'var(--bg-card-hover)',
                  borderBottom: isCollapsed ? 'none' : '1px solid var(--border-light)',
                  cursor: 'pointer',
                  userSelect: 'none',
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
                  {isCollapsed ? <ChevronRight size={16} /> : <ChevronDown size={16} />}
                  <Folder size={17} style={{ color: 'var(--accent)' }} />
                  <span style={{ fontWeight: 700, fontSize: '14px', letterSpacing: '-0.01em' }}>
                    {group.group_name}
                  </span>
                  <span
                    className="badge"
                    style={{
                      background: 'var(--bg-canvas)',
                      color: 'var(--text-secondary)',
                      border: '1px solid var(--border-light)',
                    }}
                  >
                    {group.entity_plans.length} Entities
                  </span>
                </div>

                <div style={{ fontSize: '11.5px', color: 'var(--text-dim)', fontFamily: 'var(--font-mono)' }}>
                  ID: {group.group_id}
                </div>
              </div>

              {/* Group Body */}
              {!isCollapsed && (
                <div style={{ padding: '1rem 1.25rem', display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                  {group.empty_note ? (
                    <div
                      style={{
                        padding: '1rem',
                        borderRadius: 'var(--radius-sm)',
                        background: 'var(--bg-canvas)',
                        color: 'var(--text-dim)',
                        fontStyle: 'italic',
                        textAlign: 'center',
                        fontSize: '12.5px',
                        border: '1px dashed var(--border-light)',
                      }}
                    >
                      {group.empty_note}
                    </div>
                  ) : (
                    group.entity_plans.map((ep) => {
                      const entityVisibleItems = ep.items.filter(isVisible);
                      if (filterMode !== 'all' && entityVisibleItems.length === 0) return null;

                      return (
                        <div
                          key={ep.target_root_id}
                          style={{
                            border: '1px solid var(--border-mid)',
                            borderRadius: 'var(--radius-md)',
                            background: 'var(--bg-canvas)',
                            overflow: 'hidden',
                          }}
                        >
                          {/* Entity Header (Level 2: C24) */}
                          <div
                            style={{
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'space-between',
                              padding: '0.65rem 1rem',
                              background: 'var(--bg-card)',
                              borderBottom: '1px solid var(--border-light)',
                              flexWrap: 'wrap',
                              gap: '0.5rem',
                            }}
                          >
                            <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                              <Folder size={15} style={{ color: 'var(--info)' }} />
                              <span style={{ fontWeight: 600, fontSize: '13.5px' }}>
                                {ep.target_root_name}
                              </span>
                              <span
                                className="badge"
                                style={{
                                  background: 'var(--info-bg)',
                                  color: 'var(--info)',
                                  border: '1px solid var(--info-border)',
                                }}
                              >
                                Entity Root
                              </span>
                            </div>

                            <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                              <span style={{ fontSize: '11px', color: 'var(--text-dim)', fontFamily: 'var(--font-mono)' }}>
                                ID: {ep.target_root_id}
                              </span>
                              <a
                                href={`https://drive.google.com/drive/folders/${ep.target_root_id}`}
                                target="_blank"
                                rel="noreferrer"
                                style={{ color: 'var(--text-tertiary)', display: 'inline-flex', alignItems: 'center' }}
                                title="Open on Google Drive"
                              >
                                <ExternalLink size={13} />
                              </a>
                            </div>
                          </div>

                          {/* Action Items List */}
                          <div style={{ display: 'flex', flexDirection: 'column' }}>
                            {entityVisibleItems.map((item, idx) => (
                              <div
                                key={idx}
                                style={{
                                  display: 'flex',
                                  flexDirection: 'column',
                                  padding: '0.75rem 1rem',
                                  borderBottom:
                                    idx < entityVisibleItems.length - 1
                                      ? '1px solid var(--border-table)'
                                      : 'none',
                                  background:
                                    item.action_type === 'FLAG_RED'
                                      ? 'var(--danger-bg)'
                                      : 'transparent',
                                  gap: '0.35rem',
                                }}
                              >
                                {/* Item Row Top */}
                                <div
                                  style={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'space-between',
                                    gap: '0.5rem',
                                  }}
                                >
                                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
                                    {getActionBadge(item.action_type)}
                                    <span
                                      style={{
                                        fontFamily: 'var(--font-mono)',
                                        fontSize: '13px',
                                        fontWeight: 600,
                                        color:
                                          item.action_type === 'FLAG_RED'
                                            ? 'var(--danger)'
                                            : item.action_type === 'RENAME'
                                            ? '#c084fc'
                                            : 'var(--text-primary)',
                                      }}
                                    >
                                      {item.action_type === 'RENAME' && item.current_name ? (
                                        <>
                                          <span style={{ textDecoration: 'line-through', opacity: 0.65, marginRight: '0.4rem' }}>
                                            {item.current_name}
                                          </span>
                                          &rarr; {item.folder_name}
                                        </>
                                      ) : (
                                        item.folder_name
                                      )}
                                    </span>
                                    <span style={{ fontSize: '11.5px', color: 'var(--text-dim)' }}>
                                      ({item.relative_path})
                                    </span>
                                  </div>

                                  <div style={{ fontSize: '11.5px', color: 'var(--text-tertiary)' }}>
                                    {item.reason}
                                  </div>
                                </div>

                                {/* Detailed Content Diffs */}
                                {item.action_type === 'UPDATE_DESC' && (
                                  <div
                                    style={{
                                      display: 'grid',
                                      gridTemplateColumns: '1fr 1fr',
                                      gap: '0.75rem',
                                      marginTop: '0.35rem',
                                      padding: '0.5rem 0.75rem',
                                      borderRadius: 'var(--radius-sm)',
                                      background: 'var(--bg-input)',
                                      fontSize: '12px',
                                      fontFamily: 'var(--font-mono)',
                                    }}
                                  >
                                    <div>
                                      <span style={{ color: 'var(--danger)', fontWeight: 600 }}>- Current: </span>
                                      <span style={{ color: 'var(--text-tertiary)' }}>
                                        {item.current_desc || '(Empty)'}
                                      </span>
                                    </div>
                                    <div>
                                      <span style={{ color: 'var(--success)', fontWeight: 600 }}>+ Expected: </span>
                                      <span style={{ color: 'var(--text-secondary)' }}>
                                        {item.expected_desc}
                                      </span>
                                    </div>
                                  </div>
                                )}

                                {item.action_type === 'CREATE' && item.expected_desc && (
                                  <div
                                    style={{
                                      marginTop: '0.2rem',
                                      padding: '0.4rem 0.65rem',
                                      borderRadius: 'var(--radius-sm)',
                                      background: 'var(--success-bg)',
                                      border: '1px solid var(--success-border)',
                                      fontSize: '11.5px',
                                      fontFamily: 'var(--font-mono)',
                                      color: 'var(--success)',
                                    }}
                                  >
                                    Initial description: {item.expected_desc}
                                  </div>
                                )}

                                {item.action_type === 'FLAG_RED' && (
                                  <div
                                    style={{
                                      marginTop: '0.2rem',
                                      padding: '0.5rem 0.75rem',
                                      borderRadius: 'var(--radius-sm)',
                                      background: 'rgba(244, 63, 94, 0.25)',
                                      border: '1px solid var(--danger-border)',
                                      fontSize: '12px',
                                      color: 'var(--danger)',
                                      fontWeight: 600,
                                      display: 'flex',
                                      alignItems: 'center',
                                      gap: '0.5rem',
                                    }}
                                  >
                                    <AlertTriangle size={15} />
                                    <span>
                                      Populated anomaly: Contains {item.files_count} file(s) and {item.subfolders_count} subfolder(s). PRESERVED UNTOUCHED (Strict Zero-Data-Loss Invariant).
                                    </span>
                                  </div>
                                )}
                              </div>
                            ))}
                          </div>
                        </div>
                      );
                    })
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

import React from 'react';
import { ActionItem } from '../types';
import {
  FileEdit,
  FolderPlus,
  RefreshCw,
  Trash2,
  ShieldAlert,
  CheckCircle2,
  ArrowRight,
  ExternalLink,
} from 'lucide-react';

interface ExceptionFeedProps {
  items: ActionItem[];
  onExecute: () => void;
  isExecuting: boolean;
}

export const ExceptionFeed: React.FC<ExceptionFeedProps> = ({
  items,
  onExecute,
  isExecuting,
}) => {
  // Filter out MATCH rows completely — Less is More!
  const exceptions = items.filter((item) => item.action_type !== 'MATCH');

  if (exceptions.length === 0) {
    return (
      <div
        className="card"
        style={{
          padding: '4rem 2rem',
          textAlign: 'center',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          gap: '1rem',
          borderColor: 'var(--success-border)',
          background: 'rgba(16, 185, 129, 0.04)',
        }}
      >
        <div
          style={{
            width: 48,
            height: 48,
            borderRadius: '50%',
            background: 'var(--success-bg)',
            color: 'var(--success)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            border: '1px solid var(--success-border)',
          }}
        >
          <CheckCircle2 size={26} />
        </div>
        <div>
          <h2 style={{ fontSize: '18px', fontWeight: 700, color: 'var(--text-primary)', marginBottom: '0.35rem' }}>
            All Folders In Sync
          </h2>
          <p style={{ fontSize: '13px', color: 'var(--text-dim)', maxWidth: '420px', margin: '0 auto' }}>
            Every entity clone perfectly matches the archetype template. Zero drifted, missing, or extraneous folders.
          </p>
        </div>
      </div>
    );
  }

  const getActionBadge = (action: string) => {
    switch (action) {
      case 'RENAME':
        return (
          <span className="badge badge-rename" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.3rem' }}>
            <FileEdit size={11} /> RENAME
          </span>
        );
      case 'CREATE':
        return (
          <span className="badge badge-create" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.3rem' }}>
            <FolderPlus size={11} /> MISSING FOLDER
          </span>
        );
      case 'UPDATE_DESC':
        return (
          <span className="badge badge-update" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.3rem' }}>
            <RefreshCw size={11} /> METADATA DRIFT
          </span>
        );
      case 'PRUNE_EMPTY':
        return (
          <span className="badge badge-prune" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.3rem' }}>
            <Trash2 size={11} /> UNWANTED EMPTY
          </span>
        );
      case 'FLAG_RED':
        return (
          <span className="badge badge-anomaly" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.3rem' }}>
            <ShieldAlert size={11} /> PROTECTED FOLDER
          </span>
        );
      default:
        return null;
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
      {/* Hero Sync Banner */}
      <div
        className="card"
        style={{
          padding: '1.25rem 1.5rem',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          background: 'var(--bg-card-hover)',
          borderColor: 'var(--accent)',
          boxShadow: '0 0 20px var(--accent-glow)',
          flexWrap: 'wrap',
          gap: '1rem',
        }}
      >
        <div>
          <div style={{ fontSize: '16px', fontWeight: 800, color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <span style={{ color: 'var(--accent)' }}>●</span>
            {exceptions.length} {exceptions.length === 1 ? 'Mismatch' : 'Mismatches'} Detected
          </div>
          <div style={{ fontSize: '12px', color: 'var(--text-dim)', marginTop: '0.2rem' }}>
            These folders differ from the archetype template. Applying updates will align them safely.
          </div>
        </div>

        <button
          onClick={onExecute}
          disabled={isExecuting}
          className="btn primary"
          style={{
            padding: '0.65rem 1.5rem',
            fontSize: '13.5px',
            fontWeight: 700,
            background: 'var(--accent)',
            color: '#000',
            border: 'none',
            borderRadius: 'var(--radius-sm)',
            cursor: 'pointer',
            boxShadow: '0 0 14px var(--accent-glow)',
          }}
        >
          {isExecuting ? 'Applying Changes...' : `⚡ Sync All Changes (${exceptions.length})`}
        </button>
      </div>

      {/* The Exception Feed (ONLY what doesn't match!) */}
      <div className="card" style={{ padding: '0', overflow: 'hidden' }}>
        <div style={{ padding: '0.75rem 1.25rem', borderBottom: '1px solid var(--border-light)', background: 'var(--bg-canvas)', display: 'flex', justifyContent: 'space-between' }}>
          <span style={{ fontSize: '11px', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-dim)' }}>
            Differences Requiring Attention ({exceptions.length})
          </span>
          <span style={{ fontSize: '11px', color: 'var(--text-dim)' }}>
            All compliant folders hidden (Less is More)
          </span>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column' }}>
          {exceptions.map((item, idx) => (
            <div
              key={idx}
              style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                padding: '1rem 1.25rem',
                borderBottom: idx < exceptions.length - 1 ? '1px solid var(--border-table)' : 'none',
                gap: '1rem',
                background: item.action_type === 'FLAG_RED' ? 'var(--danger-bg)' : 'transparent',
              }}
              className="table-row-hover"
            >
              {/* Left Column: What folder is it? */}
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.35rem', flex: 1 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.65rem' }}>
                  {getActionBadge(item.action_type)}
                  <span style={{ fontFamily: 'var(--font-mono)', fontSize: '13px', color: 'var(--text-tertiary)' }}>
                    {item.relative_path}
                  </span>
                </div>

                {/* Change Description */}
                <div style={{ fontSize: '14px', fontWeight: 600, color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                  {item.action_type === 'RENAME' ? (
                    <>
                      <span style={{ textDecoration: 'line-through', opacity: 0.5 }}>{item.current_name}</span>
                      <ArrowRight size={14} style={{ color: '#c084fc' }} />
                      <span style={{ color: '#c084fc', fontWeight: 700 }}>{item.folder_name}</span>
                    </>
                  ) : item.action_type === 'CREATE' ? (
                    <span style={{ color: 'var(--success)' }}>Will create folder "{item.folder_name}"</span>
                  ) : item.action_type === 'UPDATE_DESC' ? (
                    <span style={{ color: 'var(--warning)' }}>Update folder metadata to match template</span>
                  ) : item.action_type === 'PRUNE_EMPTY' ? (
                    <span style={{ color: 'var(--muted)' }}>Move empty folder "{item.folder_name}" to Trash</span>
                  ) : (
                    <span style={{ color: 'var(--danger)' }}>
                      Folder contains {item.files_count} file(s) — Preserved untouched
                    </span>
                  )}
                </div>

                <div style={{ fontSize: '12px', color: 'var(--text-dim)' }}>
                  {item.reason}
                </div>
              </div>

              {/* Right Column: Target Link if exists */}
              {item.target_id && (
                <a
                  href={`https://drive.google.com/drive/folders/${item.target_id}`}
                  target="_blank"
                  rel="noreferrer"
                  className="btn subtle"
                  style={{ padding: '0.35rem 0.6rem', fontSize: '12px', color: 'var(--text-dim)' }}
                  title="Open folder in Google Drive"
                >
                  <ExternalLink size={13} />
                </a>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

