992	
993	interface FolderInspectorProps {
994	  node: TemplateNode;
995	  vaultTags: Record<string, string[]>;
996	  onNameChange: (name: string) => void;
997	  onDescriptionChange: (desc: string) => void;
998	  onAddSubfolder: () => void;
999	  onDelete: () => void;
1000	  onRestore: () => void;
1001	  mode: 'builder' | 'raw';
1002	  setMode: (mode: 'builder' | 'raw') => void;
1003	  isRoot: boolean;
1004	}
1005	
1006	const FolderInspector: React.FC<FolderInspectorProps> = ({
1007	  node,
1008	  vaultTags,
1009	  onNameChange,
1010	  onDescriptionChange,
1011	  onAddSubfolder,
1012	  onDelete,
1013	  onRestore,
1014	  mode,
1015	  setMode,
1016	  isRoot,
1017	}) => {
1018	  const [newTagKey, setNewTagKey] = useState('');
1019	  const [newTagValInputs, setNewTagValInputs] = useState<Record<string, string>>({});
1020	
1021	  // Parse current description into structured tags
1022	  const { tags, otherLines } = useMemo(() => {
1023	    return parseDescription(node.description || '');
1024	  }, [node.description]);
1025	
1026	  // Handle adding a new tag category
1027	  const handleAddCategory = (keyName: string) => {
1028	    const cleanKey = keyName.trim();
1029	    if (!cleanKey) return;
1030	
1031	    if (tags.some((t) => t.key.toLowerCase() === cleanKey.toLowerCase())) {
1032	      return;
1033	    }
1034	
1035	    const updatedTags: TagEntry[] = [...tags, { key: cleanKey, values: [] }];
1036	    onDescriptionChange(formatDescription(updatedTags, otherLines));
1037	    setNewTagKey('');
1038	  };
1039	
1040	  // Handle adding value pill to tag
1041	  const handleAddValueToTag = (key: string, val: string) => {
1042	    const cleanVal = val.trim();
1043	    if (!cleanVal) return;
1044	
1045	    const updatedTags = tags.map((t) => {
